const jsonData = pm.response.json();

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response time is acceptable", function () {
    pm.expect(pm.response.responseTime).to.be.below(2000);
});

pm.test("Response has correct Content-Type", function () {
    pm.expect(pm.response.headers.get("Content-Type")).to.include("application/json");
});

pm.test("Response body has 'data' array", function () {
    pm.expect(jsonData).to.have.property("data");
    pm.expect(jsonData.data).to.be.an("array");
});

pm.test("Data array is non-empty", function () {
    pm.expect(jsonData.data).to.have.length.above(0);
});

pm.test("Each ledger has required fields with correct types", function () {
    jsonData.data.forEach(function (ledger) {
        pm.expect(ledger, "ledger object").to.be.an("object");
        pm.expect(ledger.id, "id").to.be.a("string").and.to.match(/^[0-9a-f-]{36}$/, "id should be a valid UUID");
        pm.expect(ledger.name, "name").to.be.a("string").and.to.have.length.above(0);
        pm.expect(ledger.currency, "currency").to.be.a("string").and.to.have.length.above(0);
        pm.expect(ledger.icon, "icon").to.be.a("string");
        pm.expect(ledger.short_name, "short_name").to.be.a("string");
        pm.expect(ledger.created_at, "created_at").to.be.a("string").and.to.match(/^\d{4}-\d{2}-\d{2}T/, "created_at should be an ISO 8601 date");
        pm.expect(ledger.last_accessed, "last_accessed").to.be.a("string").and.to.match(/^\d{4}-\d{2}-\d{2}T/, "last_accessed should be an ISO 8601 date");
    });
});

pm.test("Contains the test ledger created in this run", function () {
    const ids = jsonData.data.map(l => l.id);
    pm.expect(ids).to.include(pm.collectionVariables.get("ledgerId"));
});

